/**
 * Slides shown one at a time, paged by the reader (`design/components/carousel.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/carousel.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/carousel'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/carousel.module.css'
import Button from '../controls/Button'

export interface CarouselSlide {
  id: string
  label: string
  content: JSX.Element | string
}

export interface CarouselProps {
  defaultIndex?: number
  /**
   * The current slide, controlled as in Slider; swiping also calls `onIndexChange`.
   */
  index?: number
  /**
   * Names the carousel, such as "Product tour" rather than "Carousel".
   */
  label: string
  /**
   * Wraps from the first slide to the last and back; when off, the end buttons are disabled.
   */
  loop?: boolean
  nextLabel: string
  onIndexChange?: (index: number) => void
  /**
   * Accessible names for the previous and next buttons, in the app's language, with no default.
   */
  previousLabel: string
  /**
   * Spoken role names for the region and each slide (default `carousel` and `slide`, the APG's
   * terms); localized hosts pass both or neither.
   */
  roleDescriptions?: { carousel: string; slide: string }
  /**
   * Slides in reading order; an empty list renders nothing, and the page handles it.
   */
  slides: CarouselSlide[]
}

/** Slides shown one at a time, paged by the reader. */
export default function Carousel(given: CarouselProps): JSX.Element {
  const props = mergeProps(
    {
      defaultIndex: 0,
      loop: false,
      roleDescriptions: (() => ({ carousel: 'carousel', slide: 'slide' }))(),
    } as Defaults<CarouselProps, 'defaultIndex' | 'loop' | 'roleDescriptions'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const kept = createCell(props.index ?? props.defaultIndex)
    const scrolls = createCell(0)
    const sent = createCell(-1)
    const moving = createCell(false)
    const controls = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const viewport = elementRef<HTMLElement>()
    const measurable = createDerived(
      () => () => viewport.value !== null && viewport.value.clientWidth > 0,
    )
    const within = createDerived(
      () => (at: number) => Math.min(Math.max(at, 0), Math.max(props.slides.length - 1, 0)),
    )
    const shown = createDerived(() => within.value(props.index ?? kept.value))
    const instant = createDerived(() => () => {
      const duration =
        viewport.value === null
          ? NaN
          : parseFloat(
              getComputedStyle(viewport.value).getPropertyValue('--pm-motion-duration-surface'),
            )
      return Number.isNaN(duration) || duration <= 0
    })
    const travel = createDerived(() => (to: number) => {
      if (to === shown.value) return
      if (props.index === undefined) go.value(to, instant.value())
      else props.onIndexChange?.(to)
    })
    const resting = createDerived(
      () => (nearest: number) =>
        viewport.value !== null &&
        Math.abs(Math.abs(viewport.value.scrollLeft) - nearest * viewport.value.clientWidth) <= 1,
    )
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          slideCount: props.slides.length,
          defaultPage: props.index ?? props.defaultIndex,
          loop: props.loop,
          onPageChange: (details) => {
            void (
              measurable.value() &&
              details.page !== kept.value &&
              ((kept.value = details.page),
              details.page !== props.index && props.onIndexChange?.(details.page))
            )
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const go = createDerived(() => (to: number, now: boolean) => {
      sent.value = scrolls.value
      moving.value = true
      api.value.scrollTo(to, now)
    })
    const settle = createDerived(() => () => {
      if (viewport.value === null || !measurable.value()) return
      const nearest = within.value(
        Math.round(Math.abs(viewport.value.scrollLeft) / viewport.value.clientWidth),
      )
      if (moving.value) {
        if (scrolls.value === sent.value || !resting.value(nearest)) return
        moving.value = false
      }
      if (nearest !== api.value.page) go.value(nearest, true)
    })
    const effect1 = () => {
      void (
        props.index !== undefined &&
        ((kept.value = within.value(props.index)),
        within.value(props.index) !== api.value.page &&
          go.value(within.value(props.index), instant.value()))
      )
    }
    watchEffect(
      createMemo(() => props.index),
      effect1,
      false,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const run = () => {
        void (
          measurable.value() &&
          api.value.page !== within.value(kept.value) &&
          go.value(within.value(kept.value), true)
        )
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [viewport.value]) if (element) resize?.observe(element)
      release2 = () => {
        resize?.disconnect()
      }
      run()
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const timer = setTimeout(() => {
        settle.value()
      }, 150)
      release3 = () => clearTimeout(timer)
    }
    watchEffect(
      createMemo(() => scrolls.value),
      effect3,
      false,
    )
    onCleanup(() => release3?.())
    let release4: (() => void) | undefined
    const effect4 = () => {
      release4?.()
      const run = () => {
        void (
          viewport.value !== null &&
          viewport.value.getAttribute('tabindex') !== '0' &&
          viewport.value.setAttribute('tabindex', '0')
        )
      }
      const mutation =
        typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
      for (const element of [viewport.value])
        if (element)
          mutation?.observe(element, {
            childList: true,
            characterData: true,
            subtree: true,
            attributeFilter: ['tabindex'],
          })
      release4 = () => {
        mutation?.disconnect()
      }
      run()
    }
    onMount(effect4)
    onCleanup(() => release4?.())
    let release5: (() => void) | undefined
    const effect5 = () => {
      release5?.()
      const ran = agentMember({
        member: 'Carousel',
        element: () => root.value,
        state: () => ({
          index: shown.value,
          slides: props.slides.map((slide) => ({ id: slide.id, label: slide.label })),
        }),
        actions: {
          set: {
            argument: 'number',
            run: (value) =>
              (() => {
                if (!Number.isInteger(value) || value < 0 || value >= props.slides.length) {
                  throw new Error(
                    `There is no slide ${value}; the slides run from 0 to ${props.slides.length - 1}.`,
                  )
                }
                travel.value(value)
              })(),
          },
        },
        withholds: () => controls.value,
      })
      release5 = () => {
        ran()
      }
    }
    onMount(effect5)
    onCleanup(() => release5?.())
    return (
      <>
        {props.slides.length > 0 ? (
          <section
            role="group"
            aria-roledescription={props.roleDescriptions.carousel}
            aria-label={props.label}
            data-member="carousel"
            ref={root.attach}
          >
            {/* viewport */}
            <div
              {...mergeParts(
                { ...api.value.getItemGroupProps(), style: undefined, dir: undefined },
                {
                  class: styles.viewport,
                  tabindex: '0',
                  role: 'region',
                  'aria-label': props.label,
                  'aria-live': undefined,
                  onscroll: () => (scrolls.value += 1),
                },
              )}
              ref={viewport.attach}
            >
              <Each of={props.slides} by={(slide) => slide.id} renew>
                {(slide, at) => (
                  <div
                    {...mergeParts(
                      {
                        ...api.value.getItemProps({ index: at() }),
                        style: undefined,
                        dir: undefined,
                      },
                      {
                        class: styles.slide,
                        role: 'group',
                        'aria-roledescription': props.roleDescriptions.slide,
                        'aria-label': slide.label,
                        'aria-hidden': undefined,
                      },
                    )}
                  >
                    {typeof slide.content === 'string' ? slide.content : slide.content}
                  </div>
                )}
              </Each>
            </div>
            {/* controls */}
            <div class={styles.controls} ref={controls.attach}>
              <Button
                variant="ghost"
                tone="neutral"
                size="sm"
                iconOnly={true}
                icon="previous"
                label={props.previousLabel}
                disabled={!props.loop && shown.value === 0}
                onClick={() =>
                  travel.value(shown.value === 0 ? props.slides.length - 1 : shown.value - 1)
                }
              />
              {/* rail */}
              <span class={styles.rail}>
                <Each of={props.slides} by={(slide) => slide.id} renew>
                  {(slide, at) => (
                    <button
                      class={styles.dot}
                      type="button"
                      data-carousel-part="dot"
                      aria-label={slide.label}
                      aria-current={at() === shown.value ? true : undefined}
                      onclick={() => travel.value(at())}
                    />
                  )}
                </Each>
              </span>
              <Button
                variant="ghost"
                tone="neutral"
                size="sm"
                iconOnly={true}
                icon="next"
                label={props.nextLabel}
                disabled={!props.loop && shown.value === props.slides.length - 1}
                onClick={() =>
                  travel.value(shown.value === props.slides.length - 1 ? 0 : shown.value + 1)
                }
              />
            </div>
          </section>
        ) : null}
      </>
    )
  })
}
